require_once __DIR__ . '/../bootstrap.php';require_method('POST');require_csrf();$u=require_auth(['super_admin']);$d=request_json();$quote=trim((string)($d['quote']??''));$author=trim((string)($d['author_name']??''));if($quote===''||$author==='')json_response(['ok'=>false,'error'=>'Author and quote are required'],422);$id=(int)($d['id']??0);$vals=[($d['business_id']??'')!==''?(int)$d['business_id']:null,$author,trim((string)($d['author_role']??''))?:null,trim((string)($d['business_name']??''))?:null,$quote,max(1,min(5,(int)($d['rating']??5))),!empty($d['is_published'])?1:0,(int)($d['sort_order']??0)];if($id){$st=db()->prepare('UPDATE testimonials SET business_id=?,author_name=?,author_role=?,business_name=?,quote=?,rating=?,is_published=?,sort_order=? WHERE id=?');$st->execute([...$vals,$id]);}else{$st=db()->prepare('INSERT INTO testimonials(business_id,author_name,author_role,business_name,quote,rating,is_published,sort_order) VALUES(?,?,?,?,?,?,?,?)');$st->execute($vals);$id=(int)db()->lastInsertId();}audit((int)$u['id'],null,'testimonial_saved',['testimonial_id'=>$id]);json_response(['ok'=>true,'id'=>$id]);
